import{z as d,x as p,o as i,c as A,q as E,j as o,D as r,d as t,s,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Point-in-time 基本面","description":"","frontmatter":{"title":"Point-in-time 基本面","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pit-fundamentals.md","filePath":"quant/pit-fundamentals.md","lastUpdated":1791063341000}'),B={name:"quant/pit-fundamentals.md"};function m(u,a,F,f,h,P){const n=p("Mermaid");return i(),A("div",null,[a[2]||(a[2]=E('<h1 id="point-in-time-基本面" tabindex="-1">Point-in-time 基本面 <a class="header-anchor" href="#point-in-time-基本面" aria-label="Permalink to &quot;Point-in-time 基本面&quot;">​</a></h1><div class="epigraph"><p>回测里用的不是「现在看到的财报」，而是「当时能看到的财报」；把修订后的数字按报告期回填，等于偷看答案。</p><footer>—— 据 Kothari, Capital Markets Research in Accounting, 2001；Compustat Point-in-Time 文档整理</footer></div><p>上一课<a href="/quant/accrual-vs-cash">应计与现金流</a>给出了可排序的应计定义。定义对了仍不够：若字段按<strong>最新重述版</strong>回填到历史报告期，高应计、低账面的排序都带了事后才知道的信息。本课只补 point-in-time（PIT）语义。可用日期的日历细节——公告滞后几天、周末怎么处理——下一课再收紧。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Compustat 一类库同时提供 as-reported 与 restated。市场在公告日只能看到当时申报的数字；后续更正、重分类、差错更正是后来才进入数据库的。用终局账面权益去算 2008 年 6 月的 HML，等于把 2009 年才披露的错报当成 2008 年可交易信息。缺口是时间戳：每个基本面字段需要「在信号日 \\(t\\) 是否已存在」。</p><p><span class="marginnote">数字实例：某公司 2007 年报利润 5 亿元，2009 年重述改为 2 亿元。用 restated 表回测，2008 年 6 月的你就已经「知道」利润只有 2 亿，等于提前一年多做空了还没暴露的困境股——这 3 亿的差额就是偷看的时间距离。</span></p><p>Fama–French 构造账面市值时，用 \\(t-1\\) 年报的账面配 \\(t\\) 年 6 月的市值，中间故意留出滞后，正是为了避开「报告期结束即可交易」的幻觉。PIT 把这层谨慎写成数据约束，而不是口头上的六个月规则。</p><h3 id="pit-不是fiscal-period的别名" tabindex="-1">PIT 不是fiscal period的别名 <a class="header-anchor" href="#pit-不是fiscal-period的别名" aria-label="Permalink to &quot;PIT 不是fiscal period的别名&quot;">​</a></h3><p>报告期结束日告诉你数字<strong>关于哪一段</strong>；PIT 告诉你数字<strong>何时进入信息集</strong>。两者经常被一张「最新财报」宽表压成一列。宽表按 period_end 索引、值却是 restated，看起来整齐，回测全是前视。本课要的是记录级约束：\\((value, period\\_end, available\\_date, restatement\\_flag)\\)，信号只读 \\(available\\_date \\le t\\) 的行。</p><p><span class="marginnote">同一报告期可有 10-K、修订 10-K/A、后续重述。PIT 取的是 \\(t\\) 当日生效的那一版，不是后来合并进 vendor 主表的终局版。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>信号在交易日 \\(t\\) 生成，只允许使用 \\(available\\_date \\le t\\) 的基本面记录。若同一 period 有多次申报，按当时有效版本取。价值、盈利、应计、投资类因子全部共享这条过滤器；Fama–French 的「账面取自上年年报」是它的一个特例，不是另一套哲学。</p><p>实现上不要把 PIT 理解成「把所有字段滞后固定 \\(k\\) 个月」。滞后规则是粗糙代理：年报通常滞后两三个月，季报更短，修订可在一年后。固定滞后会让一部分公司过早用上数字，另一部分过晚。正确做法是按公司、按期、按版本对齐可用日期。</p>',13)),(i(),o(l,null,{default:r(()=>[s(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20PER%5B%22%E6%8A%A5%E5%91%8A%E6%9C%9F%E7%BB%93%E6%9D%9F%22%5D%20--%3E%20FILE%5B%22%E5%BD%93%E6%97%B6%E7%94%B3%E6%8A%A5%E7%89%88%E6%9C%AC%22%5D%0A%20%20FILE%20--%3E%20TRADE%5B%22%E4%BF%A1%E5%8F%B7%E6%97%A5%20t%22%5D%0A%20%20PER%20-.-%3E%7C%22%E7%BB%88%E5%B1%80%20restated%22%7C%20LEAK%5B%22%E5%89%8D%E8%A7%86%E5%81%8F%E5%B7%AE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"as-reported 与 restated 的术语翻译：as-reported 是「当时报纸印的那一版」，restated 是「后来勘误合订本里的那一版」。回测只允许读前者——勘误虽然更准确，但在当时还不存在。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"前视从两条缝钻进来。一条是重述：后来更正的利润、资产、股本，被写回历史期。一条是对齐错误：用 period_end 当交易日，或用 vendor 的「最后更新时间」当可用时间。PIT 库把每次申报存成快照，回测在 \\(t\\) 做 as-of 查询。没有 PIT 库时，最低限度是用公告日或申报日截断，并丢掉明显的事后修订标记。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"Kothari 把 look-ahead 列为资本市场会计研究的标准威胁。量化回测里它更直接：因子收益里有一块其实是「未来会计更正」的信息。")],-1)),a[7]||(a[7]=e("p",null,[t("后课幸存者偏差是另一类样本问题：谁还在库里。PIT 解决的是"),e("strong",null,"在库里的那些记录，你是否过早读到了终局值"),t("。两件事常被混称为「数据质量」，机制不同，要分开修。")],-1)),a[8]||(a[8]=e("p",null,"最低实现不必等到买一套完整 PIT 库。没有快照时，用 filedate/rdq 截断 as-reported 主表，丢掉明确的 restatement 标记，并禁止用 vendor 的「最终修订日」当可用日。对照实验很有用：同一因子在 restated 宽表与 as-of 规则下收益差多少，差就是前视的尺度。Fama–French 六月规则可以当作年频价值的对照，但不能拿它给日频应计或惊喜「洗白」。",-1)),(i(),o(l,null,{default:r(()=>[s(n,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20REC%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E5%8E%86%E5%8F%B2%E8%AE%B0%E5%BD%95%22%5D%20--%3E%20Q%7B%22%E5%9B%9E%E6%B5%8B%E6%97%A5%20t%20%E6%80%8E%E4%B9%88%E5%8F%96%E5%80%BC%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22as-of%20%E5%BF%AB%E7%85%A7%22%7C%20OK%5B%22%E5%BD%93%E6%97%B6%E7%94%B3%E6%8A%A5%E7%89%88%E6%9C%AC%EF%BC%9A%E5%90%88%E6%B3%95%E5%8F%AF%E8%A7%81%22%5D%0A%20%20Q%20--%3E%7C%22restated%20%E4%B8%BB%E8%A1%A8%22%7C%20L1%5B%22%E9%87%8D%E8%BF%B0%E5%9B%9E%E5%A1%AB%EF%BC%9A%E6%9C%AA%E6%9D%A5%E6%9B%B4%E6%AD%A3%E6%8F%90%E5%89%8D%22%5D%0A%20%20Q%20--%3E%7C%22period_end%20%E5%BD%93%E4%BA%A4%E6%98%93%E6%97%A5%22%7C%20L2%5B%22%E5%AF%B9%E9%BD%90%E9%94%99%E8%AF%AF%EF%BC%9A%E5%85%AC%E5%91%8A%E5%89%8D%E5%B7%B2%E5%8F%AF%E8%A7%81%22%5D%0A%20%20L1%20--%3E%20DIFF%5B%22%E5%AF%B9%E7%85%A7%E5%AE%9E%E9%AA%8C%EF%BC%9A%E4%B8%A4%E7%A7%8D%E5%8F%A3%E5%BE%84%E7%9A%84%E6%94%B6%E7%9B%8A%E5%B7%AE%20%3D%20%E5%89%8D%E8%A7%86%E5%B0%BA%E5%BA%A6%22%5D%0A%20%20L2%20--%3E%20DIFF%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不规定各国法定申报期限，也不比较 EDGAR 与交易所公告的时差——那是<a href="/quant/filing-lag-available-date">财报滞后与可用日期</a>的日历。不在此重写应计公式，也不构造 HML 的分位断点。后课默认：凡基本面信号，先声明 as-of 规则；未声明则视为用了 restated 主表，结果不可信。</p><p>后课把可用日期收成日历，把幸存者收成宇宙。本课只禁止 restated 回填。固定滞后仍可当对照，但日频信号必须记录级 as-of。Fama–French 六月规则是年频价值的粗 PIT，不是本课定义的替代。</p><p><span class="marginnote">常见误区：初学者容易以为「数据越新越准越好」，回测里恰好相反——更「准」的 restated 数据意味着更多信息量，而信息量来自未来。准确性与合法可见性是两回事，回测要的是后者。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>应计定义对了仍会前视；PIT 约束的是信息集，不是公式。</li><li>报告期结束日 ≠ 可交易日；可用日期才进入信号。</li><li>固定滞后是代理，按版本 as-of 才是 PIT。</li><li>Fama–French 的账面滞后是同一思想的粗规则。</li><li>幸存者是下一类样本问题，不要与 PIT 捆成一句话。</li><li>出处：Kothari (2001)；Compustat Point-in-Time；Fama–French 因子构造说明。</li></ul>',6))])}const T=d(B,[["render",m]]);export{C as __pageData,T as default};
